from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        best = nums[0]
        keep = 0
        delete = {}

        for num in nums:
            keep = max(keep, 0) + num
            best = max(best, keep)

            if num < 0:
                delete[num] = max(delete.get(num, 0), keep - num)

            for x in list(delete):
                if x == num:
                    continue
                delete[x] = max(delete[x], 0) + num
                best = max(best, delete[x])

        return best
